<?php use App\Core\Csrf; use App\Core\View; $labels=['single'=>'单选题','multiple'=>'多选题','judge'=>'判断题','fill'=>'填空题']; ?>
<div class="page-head"><div><h1><?= View::e($attempt['set_title']) ?></h1><p><?= $attempt['question_mode']==='random'?'随机出题':'顺序抽取' ?> · 共 <?= (int)$attempt['total_count'] ?> 题</p></div></div>
<form method="post" action="/student/practice-attempt/<?= $attempt['id'] ?>/submit" data-confirm="确定提交本次练习并查看答案？"><?= Csrf::field() ?><?php foreach($questions as$q):$options=json_decode($q['options_json'],true)?:[];$expected=json_decode($q['correct_answers_json'],true)?:[];$inputType=($q['question_type']==='multiple'||count($expected)>1)?'checkbox':'radio';?><article class="card question-card"><div class="question-number">第 <?= $q['display_order'] ?> 题 · <?= View::e($labels[$q['question_type']]??$q['question_type']) ?></div><h3><?= View::e($q['title']) ?></h3><div class="prompt"><?= nl2br(View::e($q['prompt'])) ?></div><?php if($q['question_type']==='fill'):?><div class="field top-gap"><label>你的答案</label><input name="fill[<?= $q['id'] ?>]" autocomplete="off"></div><?php else:?><div class="options"><?php foreach($options as$letter=>$text):?><label class="option"><input type="<?= $inputType ?>" name="selected[<?= $q['id'] ?>][]" value="<?= View::e($letter) ?>"><strong><?= $q['question_type']==='judge'?View::e($text):View::e($letter).'.' ?></strong><?php if($q['question_type']!=='judge'):?><span><?= View::e($text) ?></span><?php endif;?></label><?php endforeach;?></div><?php endif;?></article><?php endforeach;?><div class="sticky-actions"><span class="muted">模拟练习在整组提交后统一显示答案。</span><button class="btn btn-primary">提交练习</button></div></form>
